40	/**
41	 * Typed error for domain restriction violations.
42	 * Thrown when a navigation tool targets a domain not in allowedDomains.
43	 * Caught by mcpToolWrapper to terminate the agent immediately.
44	 */
45	export class DomainNotAllowedError extends Error {
46	  constructor(message: string) {
47	    super(message);
48	    this.name = 'DomainNotAllowedError';
49	  }
50	}
