52	// Default timeout for MCP operations
53	const MCP_TIMEOUT_MS = 60_000;
54	
55	// Maximum reconnection attempts before giving up
56	const MAX_RECONNECT_RETRIES = 3;
57	
58	// Base delay (ms) for exponential backoff between reconnection attempts
59	const RECONNECT_BASE_DELAY_MS = 500;
