82	/**
83	 * Content item from an MCP tool call response.
84	 * Can be text or image (for take_screenshot).
85	 */
86	export interface McpContentItem {
87	  type: 'text' | 'image';
88	  text?: string;
89	  /** Base64-encoded image data (for type='image') */
90	  data?: string;
91	  /** MIME type of the image (e.g., 'image/png') */
92	  mimeType?: string;
93	}
94	
95	/**
96	 * Result from an MCP tool call.
97	 */
98	export interface McpToolCallResult {
99	  content?: McpContentItem[];
100	  isError?: boolean;
101	}
