103	/**
104	 * Manages browser lifecycle and ISOLATED MCP client for the Browser Agent.
105	 *
106	 * The browser is launched and managed by chrome-devtools-mcp in --isolated mode.
107	 * Visual tools (click_at, etc.) are enabled via --experimental-vision flag.
108	 *
109	 * Key isolation property: The MCP client here does NOT register tools
110	 * in the main ToolRegistry. Tools are kept local to the browser agent.
111	 */
112	export class BrowserManager {
113	  // --- Static singleton management ---
114	  private static instances = new Map<string, BrowserManager>();
115	
116	  /**
117	   * Returns the cache key for a given config.
118	   * Uses `sessionMode:profilePath` so different profiles get separate instances.
119	   */
120	  private static getInstanceKey(config: Config): string {
121	    const browserConfig = config.getBrowserAgentConfig();
122	    const sessionMode = browserConfig.customConfig.sessionMode ?? 'persistent';
123	    const profilePath = browserConfig.customConfig.profilePath ?? 'default';
124	    return `${sessionMode}:${profilePath}`;
125	  }
126	
127	  /**
128	   * Returns an existing BrowserManager for the current config's session mode
129	   * and profile, or creates a new one.
130	   */
131	  static getInstance(config: Config): BrowserManager {
132	    const key = BrowserManager.getInstanceKey(config);
133	    let instance = BrowserManager.instances.get(key);
134	    if (!instance) {
135	      instance = new BrowserManager(config);
136	      BrowserManager.instances.set(key, instance);
137	      debugLogger.log(`Created new BrowserManager singleton (key: ${key})`);
138	    } else {
139	      debugLogger.log(
140	        `Reusing existing BrowserManager singleton (key: ${key})`,
141	      );
142	    }
143	    return instance;
144	  }
145	
146	  /**
147	   * Closes all cached BrowserManager instances and clears the cache.
148	   * Called on /clear commands and CLI exit.
149	   */
150	  static async resetAll(): Promise<void> {
151	    const results = await Promise.allSettled(
152	      Array.from(BrowserManager.instances.values()).map((instance) =>
153	        instance.close(),
154	      ),
155	    );
156	    for (const result of results) {
157	      if (result.status === 'rejected') {
158	        debugLogger.error(
159	          `Error during BrowserManager cleanup: ${result.reason instanceof Error ? result.reason.message : String(result.reason)}`,
160	        );
161	      }
162	    }
163	    BrowserManager.instances.clear();
164	  }
165	
166	  /**
167	   * Alias for resetAll — used by CLI exit cleanup for clarity.
168	   */
169	  static async closeAll(): Promise<void> {
170	    await BrowserManager.resetAll();
171	  }
172	
173	  // --- Instance state ---
174	  // Raw MCP SDK Client - NOT the wrapper McpClient
175	  private rawMcpClient: Client | undefined;
176	  private mcpTransport: StdioClientTransport | undefined;
177	  private discoveredTools: McpTool[] = [];
178	  private disconnected = false;
179	  private isClosing = false;
180	  private connectionPromise: Promise<void> | undefined;
181	
182	  /** State for action rate limiting */
183	  private actionCounter = 0;
184	  private readonly maxActionsPerTask: number;
185	
186	  /**
187	   * Whether to inject the automation overlay.
188	   * Always false in headless mode (no visible window to decorate).
189	   */
190	  private readonly shouldInjectOverlay: boolean;
191	  private readonly shouldDisableInput: boolean;
192	
193	  constructor(private config: Config) {
194	    const browserConfig = config.getBrowserAgentConfig();
195	    this.shouldInjectOverlay = !browserConfig?.customConfig?.headless;
196	    this.shouldDisableInput = config.shouldDisableBrowserUserInput();
197	    this.maxActionsPerTask =
198	      browserConfig?.customConfig.maxActionsPerTask ?? 100;
