44	export class AgentRegistry {
45	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
46	  private readonly agents = new Map<string, AgentDefinition<any>>();
47	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
48	  private readonly allDefinitions = new Map<string, AgentDefinition<any>>();
49	
50	  constructor(private readonly config: Config) {}
51	
52	  /**
53	   * Discovers and loads agents.
54	   */
55	  async initialize(): Promise<void> {
56	    coreEvents.on(CoreEvent.ModelChanged, this.onModelChanged);
57	
58	    await this.loadAgents();
59	  }
60	
61	  private onModelChanged = () => {
62	    this.refreshAgents('local').catch((e) => {
63	      debugLogger.error(
64	        '[AgentRegistry] Failed to refresh agents on model change:',
65	        e,
66	      );
67	    });
68	  };
69	
70	  /**
71	   * Clears the current registry and re-scans for agents.
72	   */
73	  async reload(): Promise<void> {
74	    this.config.getA2AClientManager()?.clearCache();
75	    await this.config.reloadAgents();
76	    this.agents.clear();
77	    this.allDefinitions.clear();
78	    await this.loadAgents();
79	    coreEvents.emitAgentsRefreshed();
80	  }
81	
82	  /**
83	   * Acknowledges and registers a previously unacknowledged agent.
84	   */
85	  async acknowledgeAgent(agent: AgentDefinition): Promise<void> {
86	    const ackService = this.config.getAcknowledgedAgentsService();
87	    const projectRoot = this.config.getProjectRoot();
88	    if (agent.metadata?.hash) {
89	      await ackService.acknowledge(
90	        projectRoot,
91	        agent.name,
92	        agent.metadata.hash,
93	      );
94	      await this.registerAgent(agent);
95	      coreEvents.emitAgentsRefreshed();
96	    }
97	  }
98	
99	  /**
100	   * Disposes of resources and removes event listeners.
101	   */
102	  dispose(): void {
103	    coreEvents.off(CoreEvent.ModelChanged, this.onModelChanged);
104	  }
