// Value of the SANDBOX env var when running under macOS Seatbelt.
const SEATBELT_SANDBOX = 'sandbox-exec';

// SANDBOX values that do NOT indicate a container sandbox.
const NON_CONTAINER_SANDBOX_VALUES = new Set([SEATBELT_SANDBOX, 'sandbox:none']);

// Hostname that resolves to the container host under Docker/Podman.
const DOCKER_HOST = 'host.docker.internal';

// Remote debugging port exposed by the host browser for container sandboxes.
const REMOTE_DEBUGGING_PORT = 9222;

/**
 * Returns true when running inside a Docker/Podman container sandbox.
 *
 * A container sandbox is detected when the SANDBOX env var is set to any
 * value other than the macOS Seatbelt marker ('sandbox-exec') or the
 * explicit "no sandbox" marker ('sandbox:none'). The CLI sets SANDBOX to the
 * container name when launching inside a container.
 */
export function isContainerSandbox(): boolean {
  const sandbox = process.env['SANDBOX'];
  return !!sandbox && !NON_CONTAINER_SANDBOX_VALUES.has(sandbox);
}

/**
 * Returns true when running inside a macOS Seatbelt filesystem sandbox.
 */
export function isSeatbeltSandbox(): boolean {
  return process.env['SANDBOX'] === SEATBELT_SANDBOX;
